                            Schema = "{\"schemaVersion\":2,\"title\":\"Arkusz C – ocena okresowa urzędnika służby cywilnej lub pracownika służby cywilnej\",\"appliesTo\":\"Stanowiska, które nie są stanowiskiem kierownika urzędu ani stanowiskiem, na którym praca polega na bezpośrednim kierowaniu pracownikami.\",\"legalBasis\":\"Rozporządzenie Prezesa Rady Ministrów z dnia 4 kwietnia 2016 r. w sprawie warunków i sposobu przeprowadzania ocen okresowych urzędników służby cywilnej i pracowników służby cywilnej (Dz. U. poz. 470), załącznik nr 4\",\"initialStatus\":\"planned\",\"statuses\":[{\"key\":\"planned\",\"label\":\"Zaplanowana\"},{\"key\":\"criteria_set\",\"label\":\"Kryteria ustalone\"},{\"key\":\"evaluated\",\"label\":\"Ocena sporządzona\"},{\"key\":\"completed\",\"label\":\"Zakończona\",\"final\":true},{\"key\":\"objection_filed\",\"label\":\"Złożono sprzeciw\",\"final\":true},{\"key\":\"cancelled\",\"label\":\"Anulowana\",\"final\":true}],\"stages\":[{\"key\":\"criteria\",\"title\":\"Ustalenie kryteriów oceny i zapoznanie z nimi ocenianego\",\"deadline\":{\"anchor\":\"start\",\"latest\":{\"days\":30}},\"completesTo\":\"criteria_set\"},{\"key\":\"evaluation\",\"title\":\"Rozmowa oceniająca i sporządzenie oceny\",\"deadline\":{\"anchor\":\"start\",\"latest\":{\"months\":24}},\"completesTo\":\"evaluated\"},{\"key\":\"acknowledgement\",\"title\":\"Zapoznanie ocenianego z oceną\",\"completesTo\":\"completed\"},{\"key\":\"objection\",\"title\":\"Sprzeciw do dyrektora generalnego urzędu\",\"optional\":true,\"deadline\":{\"anchor\":\"stage:acknowledgement\",\"latest\":{\"days\":7}},\"completesTo\":\"objection_filed\"}],\"scales\":{\"periodic\":[{\"value\":1,\"key\":\"far_below\",\"label\":\"Znacznie poniżej oczekiwań\"},{\"value\":3,\"key\":\"below\",\"label\":\"Poniżej oczekiwań\"},{\"value\":5,\"key\":\"meets\",\"label\":\"Na poziomie oczekiwań\"},{\"value\":7,\"key\":\"above\",\"label\":\"Powyżej oczekiwań\"},{\"value\":9,\"key\":\"far_above\",\"label\":\"Znacznie powyżej oczekiwań\"}]},\"scoring\":{\"scores\":\"scores\",\"average\":\"averageScore\",\"level\":\"level\",\"result\":\"result\",\"levels\":[{\"key\":\"far_below\",\"label\":\"Znacznie poniżej oczekiwań\",\"min\":1,\"max\":2},{\"key\":\"below\",\"label\":\"Poniżej oczekiwań\",\"minExclusive\":2,\"max\":4},{\"key\":\"meets\",\"label\":\"Na poziomie oczekiwań\",\"minExclusive\":4,\"max\":6},{\"key\":\"above\",\"label\":\"Powyżej oczekiwań\",\"minExclusive\":6,\"max\":8},{\"key\":\"far_above\",\"label\":\"Znacznie powyżej oczekiwań\",\"minExclusive\":8,\"max\":9}],\"positiveWhen\":[{\"rule\":\"levelIn\",\"values\":[\"meets\",\"above\",\"far_above\"]},{\"rule\":\"maxCountOfScore\",\"score\":1,\"count\":0}]},\"sections\":[{\"key\":\"part1_general\",\"part\":\"Część I\",\"title\":\"Dane\",\"stage\":\"criteria\",\"fields\":[{\"key\":\"office\",\"type\":\"text\",\"label\":\"Nazwa urzędu\",\"required\":true},{\"key\":\"evaluated\",\"type\":\"person\",\"label\":\"Dane ocenianego\",\"role\":\"evaluated\",\"required\":true,\"hint\":\"Pełna nazwa stanowiska wraz z rozszerzeniem z opisu stanowiska pracy.\"},{\"key\":\"evaluator\",\"type\":\"person\",\"label\":\"Dane oceniającego\",\"role\":\"evaluator\",\"required\":true}]},{\"key\":\"part1_criteria\",\"part\":\"Część I\",\"title\":\"Kryteria oceny i termin sporządzenia oceny\",\"stage\":\"criteria\",\"fields\":[{\"key\":\"criteria\",\"type\":\"criteriaSelection\",\"label\":\"Kryteria oceny\",\"required\":true,\"mandatory\":[{\"key\":\"knowledge\",\"label\":\"Wykorzystywanie wiedzy i doskonalenie zawodowe\"},{\"key\":\"reliability\",\"label\":\"Rzetelność\"},{\"key\":\"organization\",\"label\":\"Organizacja pracy i orientacja na osiąganie celów\"},{\"key\":\"cooperation\",\"label\":\"Współpraca\"},{\"key\":\"communication\",\"label\":\"Komunikacja\"}],\"additional\":{\"max\":3,\"from\":\"competencyModel\",\"catalog\":\"Model kompetencji służby cywilnej (Kompas Kompetencji, Ministerstwo Cyfryzacji)\"}},{\"key\":\"evaluationDueDate\",\"type\":\"date\",\"label\":\"Termin sporządzenia oceny\",\"prefill\":\"stage:evaluation\",\"required\":true},{\"key\":\"criteriaEvaluatorSignature\",\"type\":\"signature\",\"role\":\"evaluator\",\"label\":\"Potwierdzenie przeprowadzenia rozmowy (§ 5 ust. 1 rozporządzenia) i zapoznania ocenianego z kryteriami oceny oraz terminem sporządzenia oceny\"},{\"key\":\"criteriaEvaluatedSignature\",\"type\":\"signature\",\"role\":\"evaluated\"}]},{\"key\":\"part2_interview\",\"part\":\"Część II\",\"title\":\"Rozmowa oceniająca\",\"stage\":\"evaluation\",\"fields\":[{\"key\":\"evaluationInterviewDate\",\"type\":\"date\",\"label\":\"Data przeprowadzenia rozmowy oceniającej\",\"required\":true},{\"key\":\"evaluationPeriod\",\"type\":\"dateRange\",\"label\":\"Okres, w którym oceniany podlegał ocenie\",\"required\":true,\"hint\":\"Od: data zapoznania z kryteriami (część I). Do: data sporządzenia oceny na piśmie.\"}]},{\"key\":\"part2_scores\",\"part\":\"Część II\",\"title\":\"Oceny cząstkowe\",\"stage\":\"evaluation\",\"fields\":[{\"key\":\"scores\",\"type\":\"scores\",\"label\":\"Kryteria obowiązkowe i dodatkowe\",\"scale\":\"periodic\",\"itemsFrom\":\"criteria\",\"required\":true},{\"key\":\"scoresIndicators\",\"type\":\"indicatorScores\",\"label\":\"Wskaźniki behawioralne\",\"of\":\"scores\"},{\"key\":\"averageScore\",\"type\":\"average\",\"label\":\"Średnia arytmetyczna z ocen cząstkowych\",\"of\":\"scores\"}]},{\"key\":\"part2_result\",\"part\":\"Część II\",\"title\":\"Przyznanie oceny\",\"stage\":\"evaluation\",\"fields\":[{\"key\":\"level\",\"type\":\"level\",\"label\":\"Ogólny poziom spełnienia kryteriów oceny\",\"of\":\"averageScore\"},{\"key\":\"result\",\"type\":\"choice\",\"label\":\"Ocena okresowa w służbie cywilnej\",\"required\":true,\"options\":[{\"value\":\"positive\",\"label\":\"Pozytywna\"},{\"value\":\"negative\",\"label\":\"Negatywna\"}]},{\"key\":\"justification\",\"type\":\"longText\",\"label\":\"Uzasadnienie przyznanej oceny okresowej\",\"requiredWhen\":{\"field\":\"result\",\"in\":[\"negative\"]}},{\"key\":\"developmentConclusions\",\"type\":\"longText\",\"label\":\"Wnioski dotyczące indywidualnego programu rozwoju zawodowego\",\"required\":true}]},{\"key\":\"part2_previous\",\"part\":\"Część II\",\"title\":\"Dane dotyczące poprzedniej oceny okresowej urzędnika służby cywilnej\",\"stage\":\"evaluation\",\"fields\":[{\"key\":\"previousResult\",\"type\":\"choice\",\"label\":\"Ocena\",\"options\":[{\"value\":\"positive\",\"label\":\"Pozytywna\"},{\"value\":\"negative\",\"label\":\"Negatywna\"}]},{\"key\":\"previousLevel\",\"type\":\"choice\",\"label\":\"Poziom\",\"optionsFrom\":\"scoring.levels\"},{\"key\":\"previousDate\",\"type\":\"date\",\"label\":\"Data sporządzenia\"}]},{\"key\":\"part2_promotion\",\"part\":\"Część II\",\"title\":\"Wniosek o kolejny stopień służbowy\",\"stage\":\"evaluation\",\"fields\":[{\"key\":\"promotionRequest\",\"type\":\"choice\",\"label\":\"Czy do oceny okresowej dołączono wniosek o przyznanie kolejnego stopnia służbowego?\",\"required\":true,\"options\":[{\"value\":\"yes\",\"label\":\"Tak\"},{\"value\":\"no\",\"label\":\"Nie\"},{\"value\":\"not_applicable\",\"label\":\"Nie dotyczy (oceniany jest pracownikiem służby cywilnej)\"}]}]},{\"key\":\"part2_signature\",\"part\":\"Część II\",\"title\":\"Oceniający\",\"stage\":\"evaluation\",\"fields\":[{\"key\":\"finalEvaluator\",\"type\":\"person\",\"label\":\"Dane oceniającego\",\"role\":\"evaluator\",\"required\":true},{\"key\":\"evaluationEvaluatorSignature\",\"type\":\"signature\",\"role\":\"evaluator\"}]},{\"key\":\"acknowledgement\",\"part\":\"Część II\",\"title\":\"Zapoznanie z oceną\",\"stage\":\"acknowledgement\",\"fields\":[{\"key\":\"acknowledgementSignature\",\"type\":\"signature\",\"role\":\"evaluated\",\"label\":\"Przeprowadzono ze mną rozmowę oceniającą oraz zapoznałem(-łam) się z oceną okresową i wnioskami dotyczącymi indywidualnego programu rozwoju zawodowego.\"},{\"key\":\"objectionNotice\",\"type\":\"notice\",\"label\":\"Zgodnie z art. 83 ust. 1 ustawy z dnia 21 listopada 2008 r. o służbie cywilnej od oceny okresowej służy, w terminie 7 dni od dnia zapoznania się z oceną, sprzeciw do dyrektora generalnego urzędu.\"}]},{\"key\":\"part3_promotion\",\"part\":\"Część III\",\"title\":\"Wniosek o przyznanie urzędnikowi służby cywilnej kolejnego stopnia służbowego (art. 89 ust. 1 ustawy)\",\"stage\":\"evaluation\",\"visibleWhen\":{\"field\":\"promotionRequest\",\"in\":[\"yes\"]},\"fields\":[{\"key\":\"civilServant\",\"type\":\"person\",\"label\":\"Dane urzędnika służby cywilnej\",\"role\":\"evaluated\",\"required\":true},{\"key\":\"appointmentYear\",\"type\":\"year\",\"label\":\"Rok mianowania\",\"required\":true},{\"key\":\"currentRank\",\"type\":\"text\",\"label\":\"Posiadany stopień służbowy\",\"required\":true},{\"key\":\"currentRankDate\",\"type\":\"date\",\"label\":\"Data przyznania stopnia służbowego\",\"required\":true},{\"key\":\"requestedRank\",\"type\":\"text\",\"label\":\"Wnioskowany stopień służbowy\",\"required\":true},{\"key\":\"promotionMotivation\",\"type\":\"longText\",\"label\":\"Umotywowanie wniosku\",\"required\":true},{\"key\":\"promotionEvaluatorSignature\",\"type\":\"signature\",\"role\":\"evaluator\"}]}],\"competencyModel\":{\"source\":\"Model kompetencji służby cywilnej (Kompas Kompetencji, Ministerstwo Cyfryzacji)\",\"guidance\":[\"Dobierz wskaźniki do zadań i zakresu odpowiedzialności na stanowisku. Poziom „na poziomie oczekiwań” opisuje standard wykonania w tym zakresie.\",\"Oprzyj ocenę na konkretnych przykładach z ocenianego okresu. Zapisz sytuację, działanie i jego rezultat. Uwzględnij powtarzalność zachowania, złożoność sytuacji i dostępne uprawnienia.\",\"Jeśli brak było okazji do zaobserwowania zachowania, odnotuj brak podstaw do oceny danego wskaźnika.\"],\"competencies\":{\"reliability\":{\"name\":\"Rzetelność\",\"indicators\":[{\"key\":\"reliability_1\",\"text\":\"Wykonywanie zadań zgodnie z obowiązującymi standardami (przepisami, zasadami, procedurami) oraz dbałość o jakość rezultatów.\",\"levels\":{\"far_below\":\"Pomija wymagane czynności lub kontrole, przez co rezultat wymaga istotnej korekty.\",\"below\":\"Stosuje podstawowe procedury, lecz pomija część wymagań lub sprawdza rezultat dopiero po zwróceniu uwagi.\",\"meets\":\"Sprawdza aktualne wymagania, stosuje właściwą procedurę i weryfikuje rezultat przed przekazaniem.\",\"above\":\"W nietypowych sprawach ustala, które wymagania mają zastosowanie, i dobiera dodatkowe kontrole do ryzyka błędu.\",\"far_above\":\"Rozpoznaje powtarzające się przyczyny błędów i wdraża w swoim zakresie kontrole, które im zapobiegają.\"}},{\"key\":\"reliability_2\",\"text\":\"Dotrzymywanie zobowiązań (realizacja zadań) w wyznaczonym czasie.\",\"levels\":{\"far_below\":\"Przekazuje zadania po terminie, a opóźnienie zgłasza dopiero po interwencji lub upływie terminu.\",\"below\":\"Realizuje zadania w terminie przy przypomnieniach lub zgłasza zagrożenie zbyt późno, by zmienić plan.\",\"meets\":\"Dotrzymuje uzgodnionych terminów. Z wyprzedzeniem zgłasza ryzyko opóźnienia i uzgadnia dalsze kroki.\",\"above\":\"Przy zadaniach zależnych od innych ustala terminy cząstkowe i reaguje na odchylenia, zanim zagrożą zobowiązaniu.\",\"far_above\":\"Przy powtarzających się zagrożeniach identyfikuje ich przyczyny, uzgadnia zmiany w organizacji pracy i sprawdza ich wpływ na terminowość.\"}}]},\"communication\":{\"name\":\"Komunikacja\",\"indicators\":[{\"key\":\"communication_1\",\"text\":\"Koncentrowanie się na wypowiedzi rozmówcy i dbanie o wzajemne zrozumienie.\",\"levels\":{\"far_below\":\"Przerywa wypowiedź lub odpowiada, pomijając kluczowe informacje przekazane przez rozmówcę.\",\"below\":\"Wysłuchuje wypowiedzi, lecz pozostawia istotne niejasności i sprawdza swoje rozumienie dopiero po zwróceniu uwagi.\",\"meets\":\"Pozwala rozmówcy dokończyć wypowiedź, dopytuje o niejasności i potwierdza kluczowe ustalenia.\",\"above\":\"W rozmowie o niejednoznacznych kwestiach parafrazuje stanowisko rozmówcy i wyjaśnia rozbieżności w interpretacji.\",\"far_above\":\"W rozmowie wielostronnej porządkuje różne interpretacje i sprawdza, czy uczestnicy tak samo rozumieją ustalenia oraz kwestie otwarte.\"}},{\"key\":\"communication_2\",\"text\":\"Wypowiadanie się w sposób jasny i precyzyjny, dostosowany do sytuacji i rozmówcy (dobieranie stylu, języka i treści).\",\"levels\":{\"far_below\":\"Przekazuje informacje bez wskazania głównej myśli lub używa pojęć, których rozmówca nie może zrozumieć bez wyjaśnienia.\",\"below\":\"Przekazuje sedno sprawy, lecz rozmówca musi dopytywać o znaczenie, kontekst lub dalsze kroki.\",\"meets\":\"Porządkuje wypowiedź, wyjaśnia potrzebne pojęcia i dostosowuje język oraz szczegółowość do rozmówcy i sytuacji.\",\"above\":\"Wyjaśnia złożone kwestie prostym językiem, zachowując istotne rozróżnienia, i dostosowuje wyjaśnienie do pytań rozmówcy.\",\"far_above\":\"W złożonej rozmowie z osobami o różnym poziomie wiedzy przekazuje wspólną konkluzję i dobiera wyjaśnienia do potrzeb poszczególnych odbiorców.\"}},{\"key\":\"communication_3\",\"text\":\"Formułowanie jasnych i precyzyjnych wypowiedzi pisemnych dostosowanych do sytuacji i odbiorcy (dobieranie stylu, języka i treści).\",\"levels\":{\"far_below\":\"Tworzy tekst, z którego odbiorca nie może ustalić celu, stanowiska lub oczekiwanego działania.\",\"below\":\"Przekazuje główną informację, lecz tekst wymaga uzupełnienia kontekstu, uporządkowania albo doprecyzowania ustaleń.\",\"meets\":\"Formułuje spójny tekst. Wskazuje cel i kluczowe informacje, a w razie potrzeby określa dalsze działanie i termin.\",\"above\":\"W złożonej sprawie wyodrębnia najważniejszą informację, oddziela ustalenia od kwestii otwartych i precyzuje odpowiedzialność.\",\"far_above\":\"Przygotowuje jednoznaczne komunikaty dla odbiorców o różnych potrzebach, zachowując spójność danych, stanowiska i dalszych kroków.\"}},{\"key\":\"communication_4\",\"text\":\"Przedstawianie przekonujących argumentów odpowiednio do sytuacji.\",\"levels\":{\"far_below\":\"Przedstawia stanowisko bez uzasadnienia lub przywołuje argumenty niezwiązane ze sprawą.\",\"below\":\"Podaje częściowe uzasadnienie, lecz pomija przesłanki ważne dla rozmówcy lub podstawowe zastrzeżenia.\",\"meets\":\"Uzasadnia stanowisko trafnymi faktami i przykładami oraz odpowiada na główne zastrzeżenia.\",\"above\":\"W złożonej sprawie dobiera argumenty do kryteriów decyzji, odpowiada na kontrargumenty i objaśnia ograniczenia przywołanych danych.\",\"far_above\":\"Przy sprzecznych stanowiskach sprowadza dyskusję do wspólnych kryteriów, waży dowody i modyfikuje argumentację po uzyskaniu nowych informacji.\"}}]},\"knowledge\":{\"name\":\"Wykorzystywanie wiedzy i doskonalenie zawodowe\",\"indicators\":[{\"key\":\"knowledge_1\",\"text\":\"Wykorzystywanie wiedzy przy realizacji zadań na zajmowanym stanowisku pracy.\",\"levels\":{\"far_below\":\"Stosuje metody nieadekwatne do zadania mimo dostępnych wskazówek, przez co wynik wymaga ponownego opracowania.\",\"below\":\"Stosuje podstawową wiedzę w zadaniach powtarzalnych, ale przy zmianie warunków potrzebuje wskazania właściwej metody.\",\"meets\":\"Dobiera i stosuje wiedzę merytoryczną odpowiednią do zadania. W razie wątpliwości potwierdza przyjęty sposób działania.\",\"above\":\"Łączy wiedzę z kilku obszarów, by rozwiązać nietypową sprawę, i uzasadnia dobór metody oraz granice jej stosowania.\",\"far_above\":\"Sprawdza przydatność wiedzy i metod w nowych typach spraw, a sprawdzone rozwiązania przekłada na wskazówki do ponownego użycia.\"}},{\"key\":\"knowledge_2\",\"text\":\"Doskonalenie wiedzy i umiejętności niezbędnych do wykonywania zadań na zajmowanym stanowisku pracy, w szczególności wyszukiwanie i pozyskiwanie wiedzy, korzystanie z dobrych praktyk i doświadczeń innych.\",\"levels\":{\"far_below\":\"Po zmianie wymagań lub po informacji o błędach nadal wykonuje zadanie według nieaktualnych zasad lub metod.\",\"below\":\"Uzupełnia wiedzę po wskazaniu konkretnej luki, lecz potrzebuje wsparcia, by zastosować nowe umiejętności.\",\"meets\":\"Rozpoznaje luki istotne dla swoich zadań, korzysta z aktualnych materiałów i doświadczeń innych oraz stosuje zdobytą wiedzę.\",\"above\":\"Planuje rozwój pod kątem nadchodzących zadań, testuje wybrane praktyki i sprawdza ich wpływ na własną pracę.\",\"far_above\":\"Z wyprzedzeniem rozpoznaje nowe wymagania wobec swojej roli, rozwija potrzebne umiejętności i na podstawie efektów aktualizuje sposób pracy.\"}},{\"key\":\"knowledge_3\",\"text\":\"Korzystanie z dostępnych źródeł informacji, rozwiązań i technologii.\",\"levels\":{\"far_below\":\"Pomija dostępne źródła lub używa danych i narzędzi niedostosowanych do zadania.\",\"below\":\"Korzysta ze znanego źródła lub narzędzia, lecz potrzebuje wsparcia w ocenie jego aktualności albo przydatności.\",\"meets\":\"Dobiera dopuszczone źródła i narzędzia do celu oraz sprawdza aktualność informacji i poprawność wyniku.\",\"above\":\"Porównuje dostępne źródła i rozwiązania, rozstrzyga rozbieżności i dobiera narzędzie z uwzględnieniem jakości, czasu oraz zasad ochrony danych.\",\"far_above\":\"Testuje dopuszczone rozwiązania wobec konkretnych wymagań, dokumentuje ich ograniczenia i wprowadza sprawdzony sposób weryfikacji wyników.\"}}]},\"organization\":{\"name\":\"Organizacja pracy i orientacja na osiąganie celów\",\"indicators\":[{\"key\":\"organization_1\",\"text\":\"Określanie sposobu realizacji zadań/celów.\",\"levels\":{\"far_below\":\"Przystępuje do pracy bez ustalenia rezultatu ani kolejności działań, przez co pomija istotne etapy.\",\"below\":\"Ustala podstawowe kroki, lecz plan wymaga uzupełnienia o zależności, terminy lub oczekiwany rezultat.\",\"meets\":\"Określa rezultat, główne kroki, ich kolejność i terminy odpowiednie do zadania.\",\"above\":\"Dla złożonego zadania uwzględnia zależności, punkty kontroli i sposób postępowania przy przewidywalnych odchyleniach.\",\"far_above\":\"Przy wielu współzależnych działaniach uzgadnia wspólny plan, wskazuje etapy krytyczne i przygotowuje warianty realizacji.\"}},{\"key\":\"organization_2\",\"text\":\"Realizowanie zadań/celów w kolejności uwzględniającej ich wagę i pilność (ustalanie priorytetów działania).\",\"levels\":{\"far_below\":\"Wykonuje zadania według kolejności wpływu mimo znanych różnic w terminach i konsekwencjach opóźnień.\",\"below\":\"Uwzględnia pilność, lecz potrzebuje wsparcia, gdy zadania o podobnych terminach mają różną wagę.\",\"meets\":\"Ustala kolejność zadań, uwzględniając ich wagę, pilność, terminy i wpływ na inne działania.\",\"above\":\"Przy zbiegu ważnych zadań porównuje skutki przesunięć, aktualizuje priorytety i uzgadnia wpływ na zobowiązania.\",\"far_above\":\"W sytuacji konkurujących priorytetów wielu stron przedstawia kryteria wyboru, uzgadnia kolejność i wskazuje warunki jej ponownej oceny.\"}},{\"key\":\"organization_3\",\"text\":\"Dobieranie niezbędnych zasobów umożliwiających realizację zadań/celów.\",\"levels\":{\"far_below\":\"Rozpoczyna zadanie bez ustalenia podstawowych zasobów i zgłasza ich brak po wstrzymaniu pracy.\",\"below\":\"Wskazuje część zasobów, lecz potrzebuje pomocy w oszacowaniu dostępności, czasu lub nakładu pracy.\",\"meets\":\"Określa potrzebny czas, informacje, narzędzia i wsparcie. Sprawdza dostępność zasobów przed realizacją.\",\"above\":\"Dla złożonych zadań porównuje warianty wykorzystania zasobów i uzgadnia zastępstwa lub rezerwy.\",\"far_above\":\"Przy ograniczonych zasobach i współzależnych zadaniach przygotowuje warianty ich wykorzystania, wskazuje skutki wyboru i uzgadnia przesunięcia.\"}},{\"key\":\"organization_4\",\"text\":\"Dostosowywanie się do zmieniających się okoliczności.\",\"levels\":{\"far_below\":\"Kontynuuje pracę według pierwotnego planu mimo zmiany, która uniemożliwia osiągnięcie ustalonego rezultatu.\",\"below\":\"Zmienia sposób pracy po wskazaniu problemu, lecz wymaga wsparcia w ocenie konsekwencji dla dalszych działań.\",\"meets\":\"Po zmianie warunków aktualizuje sposób pracy i informuje zainteresowanych o skutkach dla uzgodnionego planu.\",\"above\":\"Przy nagłej zmianie porównuje możliwe reakcje, wdraża uzgodnione rozwiązanie i zabezpiecza najważniejsze zobowiązania.\",\"far_above\":\"Na podstawie wczesnych sygnałów przygotowuje warianty działania i koordynuje przejście na wybrany wariant, gdy warunki się zmienią.\"}},{\"key\":\"organization_5\",\"text\":\"Wytrwałość i zaangażowanie w realizację zadań/celów.\",\"levels\":{\"far_below\":\"Po napotkaniu przeszkody przerywa realizację i pozostawia zadanie bez zgłoszenia lub dalszych ustaleń.\",\"below\":\"Po trudnościach wraca do zadania po przypomnieniu lub pozostawia uzgodnione działania bez domknięcia.\",\"meets\":\"Realizuje uzgodnione etapy, reaguje na przeszkody i doprowadza zadanie do zakończenia lub uzgodnionego przekazania.\",\"above\":\"Przy powtarzających się przeszkodach podejmuje kolejne uzasadnione działania i pozyskuje wsparcie potrzebne do zakończenia zadania.\",\"far_above\":\"W długotrwałym zadaniu podtrzymuje postęp mimo kolejnych trudności i uzgadnia zmianę zakresu lub sposobu realizacji, gdy wymaga tego cel.\"}}]},\"creativity\":{\"name\":\"Kreatywność\",\"indicators\":[{\"key\":\"creativity_1\",\"text\":\"Proponowanie lub tworzenie nowych rozwiązań.\",\"levels\":{\"far_below\":\"Powiela dotychczasowe rozwiązanie mimo wskazanego problemu i możliwości zaproponowania zmiany.\",\"below\":\"Zgłasza ogólny pomysł, który wymaga doprecyzowania, aby odpowiedzieć na rozpoznaną potrzebę.\",\"meets\":\"Proponuje konkretne nowe rozwiązanie, wyjaśnia, na jaką potrzebę odpowiada, i wskazuje sposób jego wypróbowania.\",\"above\":\"Opracowuje warianty, testuje wybrane rozwiązanie w uzgodnionym zakresie i poprawia je na podstawie wyników.\",\"far_above\":\"Weryfikuje rozwiązanie według uzgodnionych kryteriów, dostosowuje je po testach i określa warunki szerszego wykorzystania.\"}},{\"key\":\"creativity_2\",\"text\":\"Nieschematyczne podejście do zadań.\",\"levels\":{\"far_below\":\"Powtarza nieskuteczny sposób pracy mimo dostępnych przesłanek do zmiany podejścia.\",\"below\":\"Dostrzega ograniczenia utrwalonego sposobu pracy, lecz potrzebuje wskazania alternatywnego podejścia.\",\"meets\":\"Kwestionuje założenie, które ogranicza rozwiązanie zadania, i wypróbowuje uzasadnioną alternatywę.\",\"above\":\"Przenosi użyteczną metodę z innego obszaru lub łączy znane metody w sposób dopasowany do nietypowego zadania.\",\"far_above\":\"Przeformułowuje złożony problem przez sprawdzenie jego założeń i porównuje skutki odmiennych podejść w praktyce.\"}}]},\"cooperation\":{\"name\":\"Współpraca\",\"indicators\":[{\"key\":\"cooperation_1\",\"text\":\"Włączanie się w działania realizowane razem z innymi osobami, jeśli istnieje taka możliwość.\",\"levels\":{\"far_below\":\"Pomija uzgodnioną część wspólnego zadania lub działa bez uwzględnienia uzgodnień zespołu.\",\"below\":\"Włącza się po ponownej prośbie lub wykonuje swoją część bez uzgodnienia zależności z innymi osobami.\",\"meets\":\"Podejmuje uzgodnioną część wspólnego zadania, koordynuje ją z innymi i przekazuje rezultaty zgodnie z ustaleniami.\",\"above\":\"Samodzielnie rozpoznaje, gdzie potrzebna jest współpraca, i uzgadnia podział działań lub oferuje konkretne wsparcie.\",\"far_above\":\"W zadaniu angażującym kilka zespołów łączy ich wkład, doprecyzowuje role i pomaga usunąć przeszkody we współdziałaniu.\"}},{\"key\":\"cooperation_2\",\"text\":\"Dbanie o przepływ informacji.\",\"levels\":{\"far_below\":\"Nie przekazuje uprawnionym osobom informacji potrzebnych do wykonania wspólnego zadania lub przekazuje je po czasie.\",\"below\":\"Przekazuje informacje po przypomnieniu albo pomija kontekst i odbiorcy muszą dopytywać o ustalenia.\",\"meets\":\"Przekazuje uprawnionym odbiorcom aktualne informacje, ustalenia i zmiany w czasie pozwalającym wykorzystać je w pracy.\",\"above\":\"Z wyprzedzeniem określa, komu i kiedy potrzebna jest informacja, oraz potwierdza dotarcie komunikatów istotnych dla dalszych działań.\",\"far_above\":\"Uzgadnia i usprawnia przepływ informacji między zespołami, dbając o aktualność ustaleń, dostęp uprawnionych osób i poufność.\"}},{\"key\":\"cooperation_3\",\"text\":\"Dbanie o dobrą atmosferę i otwartość we współpracy.\",\"levels\":{\"far_below\":\"Używa deprecjonujących komentarzy, przerywa lub przenosi rozbieżność dotyczącą zadania na ocenę osób.\",\"below\":\"Utrzymuje rzeczowy ton w typowych sytuacjach, lecz przy napięciu pomija głos innych lub wycofuje się z potrzebnego uzgodnienia.\",\"meets\":\"Odnosi się z szacunkiem do innych osób, zaprasza do wypowiedzi i omawia rozbieżności w odniesieniu do zadania.\",\"above\":\"Reaguje na sygnały napięcia, nazywa przedmiot rozbieżności i umożliwia stronom przedstawienie perspektyw.\",\"far_above\":\"W trudnej współpracy uzgadnia zasady rozmowy i sprawdza, czy pozwalają zgłaszać zastrzeżenia oraz podejmować wspólne działania.\"}},{\"key\":\"cooperation_4\",\"text\":\"Dostrzeganie wkładu pracy innych osób.\",\"levels\":{\"far_below\":\"Pomija udział innych osób, gdy przedstawia wspólny rezultat, lub nieprawidłowo przypisuje autorstwo.\",\"below\":\"Wymienia osoby uczestniczące w zadaniu po przypomnieniu albo dziękuje ogólnie, bez wskazania wkładu.\",\"meets\":\"Wskazuje konkretny wkład współpracowników i przypisuje autorstwo zgodnie z przebiegiem prac.\",\"above\":\"Zauważa także mniej widoczny wkład i wyjaśnia jego znaczenie dla wyniku, dobierając formę uznania do sytuacji.\",\"far_above\":\"Przy zadaniach z udziałem wielu osób dba o rzetelne przypisanie wkładu na różnych etapach i odzwierciedla go w podsumowaniu prac.\"}},{\"key\":\"cooperation_5\",\"text\":\"Branie pod uwagę zdania innych osób.\",\"levels\":{\"far_below\":\"Odrzuca stanowiska innych osób bez zapoznania się z ich argumentami lub bez odniesienia do nich.\",\"below\":\"Zbiera opinie, lecz wybiórczo je rozważa lub pozostawia bez odpowiedzi uwagi istotne dla zadania.\",\"meets\":\"Zasięga opinii osób związanych z zadaniem, rozważa ich argumenty i wyjaśnia sposób uwzględnienia istotnych uwag.\",\"above\":\"Aktywnie zbiera także odmienne stanowiska i porównuje je według kryteriów dotyczących wspólnego celu.\",\"far_above\":\"W sytuacji rozbieżnych stanowisk pokazuje, jak ich rozważenie wpłynęło na rozwiązanie, i wyjaśnia odrzucenie kluczowych propozycji.\"}},{\"key\":\"cooperation_6\",\"text\":\"Dzielenie się wiedzą i doświadczeniem.\",\"levels\":{\"far_below\":\"Pomija prośby o przekazanie wiedzy potrzebnej współpracownikom mimo możliwości i uprawnienia do jej udostępnienia.\",\"below\":\"Udostępnia informacje po ponownej prośbie lub w formie wymagającej dodatkowych wyjaśnień przed użyciem.\",\"meets\":\"Przekazuje uprawnionym osobom potrzebne informacje, materiały i przykłady w formie pozwalającej wykonać zadanie.\",\"above\":\"Z własnej inicjatywy dzieli się wskazówkami z ukończonych spraw, objaśnia ich zastosowanie i odpowiada na pytania.\",\"far_above\":\"Przekształca powtarzające się doświadczenia w aktualizowane materiały lub instruktaż i usprawnia je na podstawie pytań oraz wyników pracy.\"}}]},\"analytical_thinking\":{\"name\":\"Myślenie analityczne\",\"indicators\":[{\"key\":\"analytical_thinking_1\",\"text\":\"Rozróżnianie informacji istotnych i nieistotnych.\",\"levels\":{\"far_below\":\"Uwzględnia informacje poboczne jako kluczowe albo pomija dane konieczne do rozstrzygnięcia sprawy.\",\"below\":\"Wybiera podstawowe informacje, lecz potrzebuje pomocy w usunięciu zbędnych danych lub ustaleniu, czego brakuje.\",\"meets\":\"Selekcjonuje informacje według celu analizy i wskazuje braki mające znaczenie dla wyniku.\",\"above\":\"Przy obszernych lub niejednoznacznych danych stosuje jawne kryteria selekcji i sprawdza, które braki zmieniają obraz sprawy.\",\"far_above\":\"Przy wielu źródłach i konkurujących kryteriach uzasadnia zakres analizy oraz pokazuje, jak wybór danych wpływa na wynik.\"}},{\"key\":\"analytical_thinking_2\",\"text\":\"Dostrzeganie zależności między informacjami.\",\"levels\":{\"far_below\":\"Traktuje powiązane informacje oddzielnie albo przyjmuje związek na podstawie samej zbieżności.\",\"below\":\"Zauważa oczywiste powiązania, lecz pomija zależności istotne dla sprawy lub wymaga wsparcia przy ich sprawdzeniu.\",\"meets\":\"Identyfikuje zależności istotne dla zadania, sprawdza dostępne przesłanki i odróżnia ustalenia od przypuszczeń.\",\"above\":\"Porównuje alternatywne wyjaśnienia, uwzględnia dodatkowe czynniki i sprawdza, które dane potwierdzają lub podważają zależność.\",\"far_above\":\"Opisuje współwystępujące zależności, wskazuje ich wpływ na przebieg sprawy i określa dane potrzebne do rozstrzygnięcia niepewności.\"}},{\"key\":\"analytical_thinking_3\",\"text\":\"Formułowanie wniosków.\",\"levels\":{\"far_below\":\"Przedstawia wnioski bez związku z danymi lub wbrew istotnym ustaleniom.\",\"below\":\"Formułuje częściowe wnioski, lecz pomija istotne dane lub przedstawia niezweryfikowane założenia jako ustalenia.\",\"meets\":\"Formułuje logiczne wnioski, wskazuje ich podstawę i zaznacza ograniczenia zgromadzonych informacji.\",\"above\":\"W złożonej sprawie zestawia możliwe wnioski, ocenia ich oparcie w dowodach i wskazuje konsekwencje dla działania.\",\"far_above\":\"Sprawdza, czy wnioski utrzymują się po zmianie istotnych założeń, i określa, w jakich warunkach wymagają aktualizacji.\"}}]},\"negotiation\":{\"name\":\"Negocjowanie\",\"indicators\":[{\"key\":\"negotiation_1\",\"text\":\"Przygotowywanie się do negocjacji, w szczególności opracowanie projektu stanowiska, zakresu możliwych ustępstw i argumentacji.\",\"levels\":{\"far_below\":\"Przystępuje do rozmów bez określenia stanowiska, argumentów lub granic upoważnienia.\",\"below\":\"Przygotowuje stanowisko, lecz wymaga uzupełnienia argumentacji, granic ustępstw lub wariantu na wypadek braku porozumienia.\",\"meets\":\"Przygotowuje projekt stanowiska, argumenty i zakres ustępstw. Potwierdza mandat oraz wariant na wypadek braku porozumienia.\",\"above\":\"Rozpoznaje interesy stron na podstawie dostępnych informacji i przygotowuje warianty warunkowych ustępstw wraz z ich konsekwencjami.\",\"far_above\":\"Dla wielostronnych negocjacji opracowuje scenariusze, warunki przejścia między nimi oraz sposób uzyskania decyzji wykraczającej poza mandat.\"}},{\"key\":\"negotiation_2\",\"text\":\"Stosowanie technik i strategii negocjacyjnych.\",\"levels\":{\"far_below\":\"Powtarza stanowisko bez ustalenia interesów stron lub składa jednostronne ustępstwa bez jasnego celu.\",\"below\":\"Stosuje podstawowe pytania i propozycje, lecz przy zmianie przebiegu rozmów potrzebuje wskazania dalszej strategii.\",\"meets\":\"Zadaje pytania o interesy stron, stosuje obiektywne kryteria i przedstawia warunkowe propozycje w granicach mandatu.\",\"above\":\"Dostosowuje strategię do sygnałów drugiej strony, przedstawia pakiety rozwiązań i sprawdza warunki ich przyjęcia.\",\"far_above\":\"W impasie lub rozmowach wielostronnych uzgadnia sposób dalszych rozmów i buduje wymianę ustępstw opartą na priorytetach stron.\"}},{\"key\":\"negotiation_3\",\"text\":\"Osiągnięcie efektu negocjacji akceptowanego przez przełożonych.\",\"levels\":{\"far_below\":\"Przedstawia wynik, którego kluczowe warunki wykraczają poza uzgodniony mandat, lub pomija istotne zobowiązania w podsumowaniu.\",\"below\":\"Dokumentuje część ustaleń, lecz przełożony potrzebuje dodatkowych wyjaśnień o warunkach, rozbieżnościach lub skutkach.\",\"meets\":\"Przedstawia przełożonemu do akceptacji wynik zgodny z mandatem wraz z warunkami i kwestiami otwartymi. Przy braku porozumienia dokumentuje jego przyczyny.\",\"above\":\"Przedstawia do akceptacji wynik złożonych negocjacji wraz z oceną ustępstw, ryzyk i warunków wdrożenia.\",\"far_above\":\"W negocjacjach o dużych konsekwencjach przedstawia do akceptacji wykonalny wynik, chroniący kluczowe interesy, z jasno opisanymi zobowiązaniami i warunkami realizacji.\"}}]},\"public_speaking\":{\"name\":\"Wystąpienia publiczne\",\"indicators\":[{\"key\":\"public_speaking_1\",\"text\":\"Wykorzystywanie różnych środków przekazu (np. narzędzi multimedialnych) i dbałość o sposób prezentacji (w tym autoprezentacji).\",\"levels\":{\"far_below\":\"Używa materiałów nieczytelnych lub niedopasowanych do wystąpienia, co utrudnia śledzenie przekazu.\",\"below\":\"Materiały wspierają część przekazu, lecz nadmiar treści lub sposób ich prezentowania zaciera główną myśl.\",\"meets\":\"Dobiera formę i czytelne materiały do celu, odbiorców i warunków. Sprawdza działanie narzędzi i przedstawia treść w uporządkowany sposób.\",\"above\":\"W złożonym wystąpieniu łączy środki przekazu tak, by objaśniały kluczowe treści, i w razie problemu technicznego płynnie zmienia formę.\",\"far_above\":\"Przy zróżnicowanej publiczności lub trudnych warunkach dopasowuje formę na bieżąco, zachowując dostępność, spójność i precyzję przekazu.\"}},{\"key\":\"public_speaking_2\",\"text\":\"Nawiązywanie i utrzymywanie kontaktu z audytorium.\",\"levels\":{\"far_below\":\"Prowadzi wystąpienie bez reagowania na pytania lub widoczne sygnały, że odbiorcy nie nadążają za treścią.\",\"below\":\"Nawiązuje kontakt na początku, lecz później reaguje na sygnały audytorium dopiero po wyraźnej interwencji.\",\"meets\":\"Nawiązuje kontakt z odbiorcami, obserwuje ich reakcje i odnosi się do pytań lub sygnałów niezrozumienia.\",\"above\":\"Sprawdza rozumienie kluczowych treści i w razie potrzeby zmienia tempo, przykłady lub sposób angażowania audytorium.\",\"far_above\":\"W zróżnicowanym audytorium angażuje różne grupy, porządkuje rozbieżne pytania i dostosowuje interakcję do celu wystąpienia.\"}},{\"key\":\"public_speaking_3\",\"text\":\"Zarządzanie czasem wystąpienia, w szczególności przestrzeganie ram czasowych, elastyczne reagowanie na potrzeby audytorium.\",\"levels\":{\"far_below\":\"Przekracza ustalony czas lub kończy bez kluczowych treści mimo sygnałów o upływie czasu.\",\"below\":\"Kontroluje czas sporadycznie i po wydłużeniu jednej części skraca pozostałe bez uwzględnienia ich znaczenia.\",\"meets\":\"Planuje czas części, monitoruje go i w razie potrzeby skraca wątki poboczne, zachowując kluczowe treści i podsumowanie.\",\"above\":\"Przy zmianie limitu lub większej liczbie pytań świadomie przesuwa akcenty i uzgadnia przeniesienie tematów pobocznych.\",\"far_above\":\"W wydarzeniu z wieloma zależnościami koordynuje zmianę harmonogramu z prowadzącym, zachowując cel wystąpienia i uzgodnione ramy.\"}},{\"key\":\"public_speaking_4\",\"text\":\"Radzenie sobie ze stresem i emocjami, w szczególności wywołanymi krytyką i trudnymi pytaniami.\",\"levels\":{\"far_below\":\"W odpowiedzi na krytykę przechodzi do uwag osobistych, przerywa rozmowę lub traci ciągłość prezentacji.\",\"below\":\"Odpowiada reaktywnie lub odchodzi od pytania i potrzebuje wsparcia, by wrócić do rzeczowego przekazu.\",\"meets\":\"Przyjmuje trudne pytanie lub krytykę, odpowiada rzeczowo, rozpoznaje granice swojej wiedzy i wraca do głównego wątku.\",\"above\":\"Przy ostrym pytaniu oddziela istotę sprawy od tonu wypowiedzi, doprecyzowuje zarzut i utrzymuje rzeczowy przebieg rozmowy.\",\"far_above\":\"W sytuacji silnego napięcia porządkuje wymianę, odnosi się do faktów i ustala sposób odpowiedzi na kwestie wymagające weryfikacji.\"}}]},\"customer_orientation\":{\"name\":\"Orientacja na klienta/interesanta\",\"indicators\":[{\"key\":\"customer_orientation_1\",\"text\":\"Taktowne zachowanie, wyrażające szacunek i zrozumienie dla drugiej osoby.\",\"levels\":{\"far_below\":\"Używa lekceważących sformułowań, przerywa lub ignoruje uzasadnioną prośbę o wyjaśnienie.\",\"below\":\"Zachowuje poprawny ton w typowych sprawach, lecz przy napięciu odpowiada zdawkowo lub pomija zgłoszoną trudność.\",\"meets\":\"Wysłuchuje rozmówcy, odnosi się z szacunkiem do jego sytuacji i taktownie wyjaśnia także ograniczenia.\",\"above\":\"W sytuacji napięcia uznaje trudność zgłaszaną przez rozmówcę i dostosowuje język lub tempo, zachowując jasność i równe traktowanie.\",\"far_above\":\"W rozmowie o dużym napięciu obniża temperaturę wymiany, jasno stawia granice i prowadzi rozmowę w sposób respektujący godność stron.\"}},{\"key\":\"customer_orientation_2\",\"text\":\"Reagowanie na potrzeby klienta/interesanta, w szczególności rozpoznawanie jego potrzeb i proponowanie rozwiązań.\",\"levels\":{\"far_below\":\"Pomija istotę zgłoszenia lub wskazuje działanie nieadekwatne do sytuacji i dostępnej ścieżki.\",\"below\":\"Rozpoznaje typowe zgłoszenie, lecz przy niejednoznacznej sprawie pomija pytania potrzebne do dobrania rozwiązania.\",\"meets\":\"Dopytuje o potrzebę i proponuje rozwiązanie dostępne w ramach procedur albo wskazuje właściwą ścieżkę i dalsze kroki.\",\"above\":\"W złożonej sprawie ustala priorytety i bariery, porównuje dopuszczalne opcje oraz koordynuje przekazanie sprawy.\",\"far_above\":\"Przy nietypowych potrzebach angażuje właściwe osoby, uzgadnia wykonalną ścieżkę oraz sprawdza, czy przekazanie lub rozwiązanie odpowiada ustalonej potrzebie.\"}}]},\"crisis_management\":{\"name\":\"Radzenie sobie w sytuacjach kryzysowych\",\"indicators\":[{\"key\":\"crisis_management_1\",\"text\":\"Rozpoznawanie sytuacji kryzysowych i informowanie o nich zainteresowanych.\",\"levels\":{\"far_below\":\"Pomija wyraźne sygnały kryzysu lub nie przekazuje informacji właściwym osobom w wymaganym czasie.\",\"below\":\"Rozpoznaje sytuację po jej eskalacji lub przekazuje niepełny komunikat, który wymaga dodatkowego ustalania faktów.\",\"meets\":\"Rozpoznaje sytuację według kryteriów eskalacji i informuje właściwe osoby o faktach, skali zagrożenia i potrzebnych działaniach.\",\"above\":\"Łączy wczesne sygnały, weryfikuje skalę zagrożenia i przekazuje aktualizacje wraz z wyraźnym wskazaniem niepewności.\",\"far_above\":\"Przy rozproszonych sygnałach ustala, co wymaga pilnej weryfikacji, uruchamia właściwą eskalację i dba o spójność komunikatów.\"}},{\"key\":\"crisis_management_2\",\"text\":\"Podejmowanie działań mających na celu rozwiązanie kryzysu.\",\"levels\":{\"far_below\":\"Zwleka z działaniami pozostającymi w jego zakresie lub podejmuje działania pogłębiające zakłócenie.\",\"below\":\"Wykonuje pojedyncze czynności po instrukcji, lecz potrzebuje wsparcia w ustaleniu ich kolejności lub zasięgu.\",\"meets\":\"Uruchamia właściwe działania w granicach uprawnień, zabezpiecza priorytetowe sprawy i przekazuje kwestie wykraczające poza swój zakres.\",\"above\":\"Dostosowuje działania do rozwoju sytuacji, uzgadnia kolejność i zasoby oraz weryfikuje skuteczność podjętej reakcji.\",\"far_above\":\"W złożonym kryzysie koordynuje działania w swoim zakresie, rozstrzyga kolizje priorytetów i uzgadnia warunki przejścia do stabilizacji.\"}},{\"key\":\"crisis_management_3\",\"text\":\"Wyciąganie wniosków z sytuacji kryzysowych.\",\"levels\":{\"far_below\":\"Zamyka sprawę bez ustalenia przyczyn i bez reakcji na powtórzenie się problemu.\",\"below\":\"Wskazuje bezpośredni problem, lecz pozostawia zalecenia bez konkretnego działania lub terminu.\",\"meets\":\"Odtwarza przebieg zdarzenia, rozpoznaje przyczyny i uzgadnia działania, odpowiedzialność oraz terminy.\",\"above\":\"Weryfikuje przyczyny z uczestnikami, wdraża zmiany w swoim zakresie i sprawdza ich skuteczność.\",\"far_above\":\"Przekłada wnioski z kryzysu na zmiany procedur lub ćwiczeń, uzgadnia ich zastosowanie i po wdrożeniu ponownie ocenia ryzyko.\"}}]},\"strategic_management\":{\"name\":\"Zarządzanie strategiczne\",\"indicators\":[{\"key\":\"strategic_management_1\",\"text\":\"Tworzenie wizji oraz wyznaczanie celów strategicznych w oparciu o całościowe i perspektywiczne widzenie organizacji, otoczenia oraz strategie rozwoju.\",\"levels\":{\"far_below\":\"Nie określa kierunku działania albo formułuje cele oderwane od misji i uwarunkowań organizacji.\",\"below\":\"Formułuje ogólny kierunek, lecz pomija część istotnych uwarunkowań lub nie wskazuje priorytetów.\",\"meets\":\"Wyznacza spójny kierunek i cele strategiczne na podstawie misji, danych o organizacji i analizy otoczenia.\",\"above\":\"Porównuje scenariusze rozwoju, uzasadnia wybór priorytetów i określa założenia wymagające okresowej weryfikacji.\",\"far_above\":\"Uzgadnia kierunek wobec rozbieżnych interesów, rozstrzyga długofalowe kompromisy i wyznacza warunki aktualizacji strategii.\"}},{\"key\":\"strategic_management_2\",\"text\":\"Formułowanie celów operacyjnych na podstawie celów strategicznych.\",\"levels\":{\"far_below\":\"Wyznacza zadania bez powiązania z celami strategicznymi lub bez określenia oczekiwanych rezultatów.\",\"below\":\"Wskazuje powiązanie z kierunkiem strategicznym, lecz cele operacyjne pozostawia bez miernika, terminu lub odpowiedzialności.\",\"meets\":\"Przekłada cele strategiczne na konkretne rezultaty operacyjne, określając mierniki, terminy i odpowiedzialność.\",\"above\":\"Uzgadnia cele operacyjne między obszarami, uwzględnia zależności i rozstrzyga konflikty priorytetów oraz zasobów.\",\"far_above\":\"Sprawdza, czy wyniki operacyjne przekładają się na efekty strategiczne, i na tej podstawie aktualizuje uzgodnione cele.\"}},{\"key\":\"strategic_management_3\",\"text\":\"Analiza ryzyka planowanych działań o charakterze strategicznym.\",\"levels\":{\"far_below\":\"Podejmuje planowanie strategiczne bez rozpoznania istotnych zagrożeń lub ignoruje udokumentowane ryzyka.\",\"below\":\"Wymienia główne ryzyka, lecz pomija ich skalę, działania ograniczające lub odpowiedzialność.\",\"meets\":\"Ocenia prawdopodobieństwo i skutki istotnych ryzyk oraz określa działania, odpowiedzialność i sposób monitorowania.\",\"above\":\"Analizuje zależności między ryzykami, porównuje scenariusze i ustala progi uruchomienia działań ograniczających.\",\"far_above\":\"Sprawdza odporność wybranej strategii na zmianę warunków, ustala sygnały ostrzegawcze i aktualizuje reakcje w cyklu przeglądów.\"}}]},\"people_management\":{\"name\":\"Zarządzanie ludźmi\",\"indicators\":[{\"key\":\"people_management_1\",\"text\":\"Przydzielanie zakresu odpowiedzialności, zadań i uprawnień pracownikom (delegowanie zadań).\",\"levels\":{\"far_below\":\"Przydziela zadanie bez określenia rezultatu, odpowiedzialności lub uprawnień koniecznych do wykonania.\",\"below\":\"Określa część oczekiwań, lecz pozostawia niejasność co do granic decyzji, terminu lub sposobu przekazania wyniku.\",\"meets\":\"Ustala z pracownikiem rezultat, termin, zakres odpowiedzialności, uprawnienia i sposób uzgadniania wyjątków.\",\"above\":\"Dopasowuje zakres samodzielności i wsparcia do złożoności zadania oraz przygotowania pracownika, a przy zależnościach uzgadnia role.\",\"far_above\":\"W zadaniach przekrojowych porządkuje granice decyzji między rolami i na podstawie efektów koryguje podział odpowiedzialności.\"}},{\"key\":\"people_management_2\",\"text\":\"Monitorowanie realizacji zadań oraz w razie potrzeby podejmowanie działań korygujących lub zapobiegawczych.\",\"levels\":{\"far_below\":\"Sprawdza stan zadania dopiero po terminie lub po ujawnieniu problemu mimo dostępnych sygnałów odchylenia.\",\"below\":\"Monitoruje zadania doraźnie, ale nie uzgadnia działań po rozpoznaniu odchylenia lub sprawdza je z opóźnieniem.\",\"meets\":\"Ustala punkty kontroli, sprawdza postęp względem oczekiwań i uzgadnia korektę wraz z terminem sprawdzenia efektu.\",\"above\":\"Dostosowuje monitoring do ryzyka i samodzielności pracowników oraz usuwa przeszkody, zanim wpłyną na wynik.\",\"far_above\":\"Wprowadza spójny sposób monitorowania, identyfikuje powtarzalne przyczyny odchyleń i sprawdza skuteczność działań zapobiegawczych.\"}},{\"key\":\"people_management_3\",\"text\":\"Motywowanie pracowników.\",\"levels\":{\"far_below\":\"Pomija zgłaszane bariery i wkład pracowników lub reaguje w sposób zniechęcający do podejmowania inicjatywy.\",\"below\":\"Stosuje ogólne zachęty i sporadyczne pochwały, bez powiązania ich z konkretnym wkładem albo potrzebami pracownika.\",\"meets\":\"Wyjaśnia znaczenie zadań, docenia konkretny wkład i reaguje na zgłaszane bariery w zakresie swoich możliwości.\",\"above\":\"Dobiera formy uznania, samodzielności i wsparcia na podstawie rozmów z pracownikami oraz sprawdza ich efekty.\",\"far_above\":\"Diagnozuje powtarzające się organizacyjne przyczyny spadku zaangażowania i w uzgodnionym zakresie wprowadza oraz ocenia zmiany.\"}},{\"key\":\"people_management_4\",\"text\":\"Udzielanie pracownikom informacji zwrotnej opartej na ocenie ich zaangażowania i sposobu realizacji zadań.\",\"levels\":{\"far_below\":\"Pomija potrzebną informację zwrotną lub zastępuje ją ogólną oceną osoby bez wskazania zachowania.\",\"below\":\"Przekazuje feedback z opóźnieniem lub bez konkretnego przykładu i informacji o oczekiwanym działaniu.\",\"meets\":\"Omawia konkretne zachowanie i jego wpływ, wysłuchuje perspektywy pracownika oraz uzgadnia, co utrzymać lub zmienić.\",\"above\":\"W trudnych rozmowach odwołuje się do sprawdzonych przykładów, uzgadnia wykonalne działania i wraca do ich efektów.\",\"far_above\":\"Dopasowuje cykl rozmów do sytuacji pracowników, sprawdza zmianę na podstawie obserwacji i aktualizuje uzgodnienia.\"}},{\"key\":\"people_management_5\",\"text\":\"Rozwiązywanie konfliktów.\",\"levels\":{\"far_below\":\"Pozostawia zgłoszony konflikt bez reakcji albo odnosi się do niego bez wysłuchania stron i ustalenia faktów.\",\"below\":\"Podejmuje interwencję po nasileniu sporu, ale nie doprowadza do jasnego uzgodnienia działań lub dalszej ścieżki.\",\"meets\":\"Wysłuchuje stron, ustala przedmiot sporu, uzgadnia działania i sprawdza ich wykonanie albo kieruje sprawę we właściwym trybie.\",\"above\":\"Reaguje na wczesne oznaki konfliktu, porządkuje interesy stron i pomaga uzgodnić trwałe zasady współpracy.\",\"far_above\":\"Rozpoznaje powtarzalne źródła sporów, wprowadza zmiany w organizacji współpracy i sprawdza ich wpływ na przebieg konfliktów.\"}},{\"key\":\"people_management_6\",\"text\":\"Wspieranie pracowników w rozwoju zawodowym, w szczególności identyfikowanie potrzeb rozwojowych, proponowanie działań rozwojowych oraz monitorowanie ich realizacji.\",\"levels\":{\"far_below\":\"Pomija rozpoznane potrzeby rozwojowe lub kieruje na działania bez powiązania z zadaniami i potrzebami pracownika.\",\"below\":\"Ustala pojedyncze działania rozwojowe, lecz nie określa celu, terminu lub sposobu sprawdzenia efektu.\",\"meets\":\"Rozpoznaje potrzeby z pracownikiem, uzgadnia cel, działania i terminy oraz omawia postęp i zastosowanie w pracy.\",\"above\":\"Dobiera rozwój do luki i przyszłych zadań, łączy różne formy uczenia oraz modyfikuje plan na podstawie efektów.\",\"far_above\":\"Z wyprzedzeniem planuje rozwój pod kątem przyszłych potrzeb zespołu i sprawdza, jak działania przekładają się na samodzielność oraz jakość pracy.\"}}]},\"decisions\":{\"name\":\"Podejmowanie decyzji i odpowiedzialność\",\"indicators\":[{\"key\":\"decisions_1\",\"text\":\"Wypracowywanie alternatywnych rozwiązań na podstawie analizy informacji, w szczególności potencjalnego ryzyka.\",\"levels\":{\"far_below\":\"Przedstawia jedną opcję bez analizy dostępnych informacji i pomija istotne ryzyko.\",\"below\":\"Wskazuje alternatywy, lecz porównuje je wybiórczo albo pomija ważne konsekwencje i ograniczenia.\",\"meets\":\"Porównuje wykonalne warianty według istotnych kryteriów i wskazuje główne ryzyka oraz ograniczenia.\",\"above\":\"W złożonej sprawie sprawdza kluczowe założenia, porównuje scenariusze i wskazuje działania ograniczające ryzyko.\",\"far_above\":\"Przy dużej niepewności ocenia odporność wariantów na zmianę założeń oraz określa warunki wyboru, korekty lub wycofania.\"}},{\"key\":\"decisions_2\",\"text\":\"Podejmowanie decyzji (decyzyjność).\",\"levels\":{\"far_below\":\"Zwleka z rozstrzygnięciem pomimo dostępnych przesłanek albo podejmuje decyzję bez niezbędnych ustaleń lub poza zakresem uprawnień.\",\"below\":\"Podejmuje decyzje w typowych sprawach po przypomnieniu lub odkłada złożone rozstrzygnięcie bez wskazania brakujących przesłanek i terminu.\",\"meets\":\"Podejmuje i komunikuje uzasadnioną decyzję w czasie adekwatnym do sprawy. W razie potrzeby uzyskuje konsultację lub przekazuje sprawę zgodnie z uprawnieniami.\",\"above\":\"Terminowo rozstrzyga sprawy złożone na podstawie kluczowych informacji i określa przesłanki ponownej oceny decyzji.\",\"far_above\":\"W warunkach presji i niepewności dobiera tryb decyzji do jej skutków i odwracalności oraz określa warunki dalszych rozstrzygnięć.\"}},{\"key\":\"decisions_3\",\"text\":\"Przyjmowanie odpowiedzialności za efekty podjętych decyzji.\",\"levels\":{\"far_below\":\"Nie wyjaśnia skutków swojej decyzji lub pozostawia ujawnione konsekwencje bez reakcji w swoim zakresie.\",\"below\":\"Odnosi się do skutków po interwencji, lecz nie ustala dalszych działań albo nie sprawdza ich wykonania.\",\"meets\":\"Wyjaśnia przesłanki decyzji, monitoruje jej skutki i podejmuje potrzebną korektę w swoim zakresie.\",\"above\":\"W razie niekorzystnych skutków informuje zainteresowanych, inicjuje działania naprawcze i potwierdza ich wykonanie.\",\"far_above\":\"Przy decyzjach o szerokich konsekwencjach monitoruje skutki w dłuższym okresie i przekłada wnioski oraz rezultaty korekt na kolejne decyzje.\"}}]}}}}",
                            Title = "Arkusz C – ocena okresowa urzędnika służby cywilnej lub pracownika służby cywilnej",
                            Version = 2
                        });
                });

            modelBuilder.Entity("Busola.Database.Entities.Location", b =>
                {
                    b.Property<int>("Id")
                        .ValueGeneratedOnAdd()
